def min_problems_to_prepare(n, m, required_complexities, prepared_complexities):
    dp = [float('inf')] * (max(required_complexities[-1], max(prepared_complexities)) + 1)
    dp[0] = 0

    for comp in prepared_complexities:
        for j in range(comp, len(dp)):
            dp[j] = min(dp[j], dp[j - comp])

    for req in required_complexities:
        if dp[req] == float('inf'):
            return -1  # If any required complexity cannot be achieved, return -1

    return sum(1 for req in required_complexities if dp[req] > 0)

# Example usage:
import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
m = int(data[1])
required_complexities = list(map(int, data[2:2+n]))
prepared_complexities = list(map(int, data[2+n:]))

result = min_problems_to_prepare(n, m, required_complexities, prepared_complexities)
print(result)
